/**
 * Where a provider's page is on everyapp.com: one page per company
 * (`landing-page/content/docs/providers/<company>.mdx`), each with a
 * section per way in (API key, connect accounts, sign in). A catalog
 * entry or OAuth preset maps to its company's page; a provider a Gateway
 * registered from its own spec has none, so it gets the page on custom
 * providers.
 */
import { CAPABILITIES, OAUTH_PRESETS } from "@every-app/sdk/internal";
import chalk from "chalk";
// The same map the pages are generated by (src/docs/providerPages.ts), so a link never misses its page.
import { COMPANY_OF } from "@/docs/providerGuides";
import { providerCompanies } from "@/docs/providerPages";
import { CLI } from "@/lib/output/command";
import { KEPT_SPACE, type Step, type StepLink } from "@/lib/output/steps";

const SITE = "https://everyapp.com";

/** The company page `id` is on: `google` for `google-workspace`, `github` for `github-oauth`. */
function providerCompany(id: string): string {
  return COMPANY_OF[id] ?? id.replace(/-oauth$/, "");
}

/** The page to read before setting `id` up: its company's, or the custom-providers page for one the catalog doesn't ship. */
export function providerDocsUrl(id: string): string {
  const shipped = Object.hasOwn(CAPABILITIES, id) || Object.hasOwn(OAUTH_PRESETS, id);
  return `${SITE}/docs/providers/${shipped ? providerCompany(id) : "custom"}`;
}

/**
 * The provider page's "connect accounts" steps for `id`, as the Markdown
 * they are written in, or undefined when its page has generic steps (no
 * guide, or a company with several OAuth clients).
 */
function connectGuide(id: string): readonly string[] | undefined {
  const company = providerCompanies().find((entry) => entry.clients.some((client) => client.id === id));
  const steps = company?.clients.length === 1 ? company.guide.connect : undefined;
  return steps?.length ? steps : undefined;
}

/**
 * The provider page's "API key" steps for `id`, as the Markdown they are
 * written in, or undefined when its page has generic steps (no guide, or a
 * company with several keys) or it is a proxy, which has no key to paste.
 */
function keyGuide(id: string): readonly string[] | undefined {
  const company = providerCompanies().find((entry) => entry.keys.some(([key]) => key === id));
  const [, capability] = company?.keys[0] ?? [];
  const proxy = capability?.mode === "ai" && capability.kind === "proxy";
  const steps = company?.keys.length === 1 && !proxy ? company.guide.key : undefined;
  return steps?.length ? steps : undefined;
}

/**
 * A page's step, for a terminal: the page shows the redirect URI above its
 * steps and calls the CLI `everyapp`; a terminal shows the URI under the
 * step that names it, and names the CLI as this run does.
 */
const named = (step: string) => step.replace(/redirect URI above/g, "redirect URI").replace(/`everyapp /g, `\`${CLI} `);

/**
 * Those steps, numbered, as plain text for a script (`--json`): a link is
 * `text (url)`, and the step that mentions the redirect URI gets the URI
 * on its own line.
 */
export function providerConnectSteps(id: string, redirectUri: string): string[] | undefined {
  return connectGuide(id)?.map((step, index) => {
    const numbered = `${index + 1}. ${plainText(named(step))}`;
    return /redirect URI/.test(step) ? `${numbered}\n   ${redirectUri}` : numbered;
  });
}

/** The page's key steps, numbered, as plain text for a script (`--json`). */
export function providerKeySteps(id: string): string[] | undefined {
  return keyGuide(id)?.map((step, index) => `${index + 1}. ${plainText(named(step))}`);
}

/** The page's key steps for a person's screen: the same words, each link's URL under its step. */
export function providerKeyGuide(id: string): Step[] | undefined {
  return keyGuide(id)?.map((markdown) => shownStep(named(markdown)));
}

/**
 * Those steps for a person's screen (lib/output/steps.ts): the same words,
 * each link's URL under its step, and the redirect URI under the step that
 * mentions it.
 */
export function providerConnectGuide(id: string, redirectUri: string): Step[] | undefined {
  return connectGuide(id)?.map((markdown) => {
    const step = shownStep(named(markdown));
    return /redirect URI/.test(markdown)
      ? { ...step, links: [...step.links, { label: "Redirect URI", url: redirectUri }] }
      : step;
  });
}

/**
 * Markdown as a step for the terminal: `**bold**` bold, a command of this
 * CLI bold and kept on one line, other code ticks dropped, a link left as
 * its words with its URL apart.
 */
function shownStep(markdown: string): { text: string; links: StepLink[] } {
  const links: StepLink[] = [];
  const text = markdown
    .replace(/\[([^\]]+)\]\(([^)\s]+)\)/g, (_link: string, label: string, href: string) => {
      links.push({ label: label.replace(/\*\*|`/g, ""), url: href.startsWith("/") ? `${SITE}${href}` : href });
      return label;
    })
    .replace(/\*\*([^*]+)\*\*/g, (_bold: string, words: string) => chalk.bold(words))
    .replace(/`([^`]+)`/g, (_ticks: string, code: string) =>
      code.startsWith(`${CLI} `) ? chalk.bold(code.replaceAll(" ", KEPT_SPACE)) : code,
    );
  return { text, links };
}

/** Markdown to terminal text: `**bold**` and code ticks dropped, links as `text (url)`, or the bare URL when the text is the URL and a space follows. */
export function plainText(markdown: string): string {
  return markdown
    .replace(/\[([^\]]+)\]\(([^)\s]+)\)/g, (link: string, text: string, href: string, at: number, whole: string) => {
      const url = href.startsWith("/") ? `${SITE}${href}` : href;
      // Bare only when nothing but a space or the end follows: a terminal would link trailing punctuation.
      const spaced = /^(\s|$)/.test(whole.slice(at + link.length));
      return spaced && url.replace(/^https?:\/\//, "").replace(/\/$/, "") === text.replace(/\/$/, "") ? url : `${text} (${url})`;
    })
    .replace(/\*\*([^*]+)\*\*/g, "$1")
    .replace(/`([^`]+)`/g, "$1");
}
